void kernel_ludcmp(double A[40][40], double b[40], double x[40], double y[40]) {
    int i, j, k;
    double w;

    // LU decomposition
    for (i = 0; i < 40; i++) {
        for (j = 0; j < i; j++) {
            w = A[i][j];
            for (k = 0; k < j; k++) {
                w -= A[i][k] * A[k][j];
            }
            A[i][j] = w / A[j][j];
        }
        for (j = i; j < 40; j++) {
            w = A[i][j];
            for (k = 0; k < i; k++) {
                w -= A[i][k] * A[k][j];
            }
            A[i][j] = w;
        }
    }

    // Forward substitution: Ly = b
    for (i = 0; i < 40; i++) {
        w = b[i];
        for (j = 0; j < i; j++) {
            w -= A[i][j] * y[j];
        }
        y[i] = w;
    }

    // Backward substitution: Ux = y
    for (i = 39; i >= 0; i--) {
        w = y[i];
        for (j = i + 1; j < 40; j++) {
            w -= A[i][j] * x[j];
        }
        x[i] = w / A[i][i];
    }
}

