#include "ludcmp.h"

void kernel_ludcmp(double A[40][40], double b[40], double x[40], double y[40]) {
    int i, j, k;
    double w;

    // LU decomposition (Doolittle, no pivoting), performed in-place on A.
    for (i = 0; i < 40; i++) {
        // Compute lower-triangular entries L(i,j), stored in A[i][j] for j < i.
        for (j = 0; j < i; j++) {
            w = A[i][j];
            for (k = 0; k < j; k++) {
                w -= A[i][k] * A[k][j];
            }
            A[i][j] = w / A[j][j];
        }

        // Compute upper-triangular entries U(i,j), stored in A[i][j] for j >= i.
        for (j = i; j < 40; j++) {
            w = A[i][j];
            for (k = 0; k < i; k++) {
                w -= A[i][k] * A[k][j];
            }
            A[i][j] = w;
        }
    }

    // Forward substitution: solve L * y = b.
    for (i = 0; i < 40; i++) {
        w = b[i];
        for (j = 0; j < i; j++) {
            w -= A[i][j] * y[j];
        }
        y[i] = w;
    }

    // Backward substitution: solve U * x = y.
    for (i = 39; i >= 0; i--) {
        w = y[i];
        for (j = i + 1; j < 40; j++) {
            w -= A[i][j] * x[j];
        }
        x[i] = w / A[i][i];
    }
}
